#include "execution_system.hpp"
int main(int argc,char**argv){try{ventus_timing::require(argc>=2,"usage: execution program.txt [skip]");std::ifstream in(argv[1]);ventus_timing::require(bool(in),"cannot open input");int reset,offer,s0,s1;in>>reset>>offer>>s0>>s1;std::vector<ventus_timing::Instruction>p;uint32_t pc,w;while(in>>std::hex>>pc>>w)p.push_back(ventus_timing::decode(pc,w));ventus_timing::require(!p.empty(),"empty program");auto r=ventus_timing::run(p,{s0,s1},reset,offer,argc>2&&std::string(argv[2])=="skip");for(auto&e:r.execution)std::cout<<e.cycle<<'\t'<<e.kind<<'\t'<<e.pc<<'\t'<<e.order<<'\n';for(auto&e:r.writes){std::cout<<e.twice_cycle<<"\tphysical_write\t"<<e.address;for(auto x:e.mask)std::cout<<'\t'<<x;std::cout<<'\n';}std::cout<<r.host<<"\thost_return\n"<<r.steps<<"\tsteps\n"<<r.skipped<<"\tskipped\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
